/**
 * Attach the overlays to a vocab deck (non-mutating). Items without an
 * overlay pass through unchanged; display falls back to the zh source via
 * `pickLocalized`. `overlays` is injectable for tests only.
 */
export function applyVocabularyI18n(
  items: VocabularyItem[],
  overlays: Record<string, VocabularyI18nEntry> = vocabularyI18n
): VocabularyItem[] {
  return items.map((item) => {
    const overlay = overlays[item.id];
    if (!overlay) return item;
    const next: VocabularyItem = { ...item };
    if (overlay.meaning) next.meaningI18n = overlay.meaning;
    if (overlay.example && item.examples[0]) {
      next.examples = [
        { ...item.examples[0], meaningI18n: overlay.example },
        ...item.examples.slice(1)
      ];
    }
    return next;
  });
}
